typedef unsigned int u_int;
typedef unsigned int u_long128 __attribute__((mode(TI)));

struct sceIpuDmaEnv
{
    u_int d4madr;
    u_int d4tadr;
    u_int d4qwc;
    u_int d4chcr;
    u_int d3madr;
    u_int d3qwc;
    u_int d3chcr;
    u_int ipubp;
    u_int ipuctrl;
};

typedef struct
{
    long pts;
    long dts;
    int pos;
    int len;
} TimeStamp;

typedef struct
{
    u_long128 *data;
    u_long128 *tag;
    int n;
    int dmaStart;
    int dmaN;
    int readBytes;
    int buffSize;
    sceIpuDmaEnv env;
    int sema;
    int isActive;
    long totalBytes;
    TimeStamp *ts;
    int n_ts;
    int count_ts;
    int wt_ts;
} ViBuf;

#define TS_NONE (-1)
#define VIBUF_ELM_SIZE 2048
#define min(a,b) (((a) < (b)) ? (a) : (b))
#define max(a,b) (((a) > (b)) ? (a) : (b))

static inline int IsPtsInRegion( int tgt, int pos, int len, int size )
{
    int tgt1 = (tgt + size - pos) % size;
    return tgt1 < len;
}

static int viBufModifyPts( ViBuf* f, TimeStamp* new_ts )
{
    TimeStamp   *ts;
    int         rd = ( f->wt_ts - f->count_ts + f->n_ts ) % f->n_ts, datasize =  VIBUF_ELM_SIZE * f->n, loop = 1;

    if( f->count_ts > 0 )
    {
        while( loop )
        {
            ts = f->ts + rd;
            if( ts->len == 0 || new_ts->len == 0 )
            {
                break;
            }
            if( IsPtsInRegion(ts->pos, new_ts->pos, new_ts->len, datasize) )
            {
                int len = min( new_ts->pos + new_ts->len - ts->pos, ts->len );

                ts->pos = (ts->pos + len) % datasize;
                ts->len -= len;
                if( ts->len == 0 )
                {
                    if( ts->pts >= 0 )
                    {
                        ts->pts = TS_NONE;
                        ts->dts = TS_NONE;
                        ts->pos = 0;
                        ts->len = 0;
                    }
                    f->count_ts = max(f->count_ts - 1, 0);
                }
            }
            else
            {
                loop = 0;
            }
            rd = (rd + 1) % f->n_ts;
        }
    }
    return 0;
}
